<?php require_once __DIR__.'/includes/auth.php';require_user();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT r.*,u.name,e.title,e.event_date,e.start_time,e.end_time,e.venue,e.image_url FROM registrations r JOIN users u ON u.id=r.user_id JOIN events e ON e.id=r.event_id WHERE r.id=? AND r.user_id=?");$s->execute([$id,$_SESSION['user_id']]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Ticket not found.');}$s=$pdo->prepare('SELECT checked_in_at FROM checkins WHERE registration_id=?');$s->execute([$id]);$checked=$s->fetchColumn();$pageTitle='Your ticket';require __DIR__.'/includes/header.php'; ?><section class="section section-soft"><div class="container"><div class="ticket" id="ticket"><div class="d-flex justify-content-between align-items-start"><div><div class="brand"><span class="brand-mark"><i class="bi bi-ticket-perforated-fill"></i></span> CampusPass</div><p class="muted mt-3 mb-1">OFFICIAL EVENT TICKET</p><h1 class="h2"><?=e($r['title'])?></h1></div><div class="ticket-qr" data-qr-token="<?=e($r['qr_token'])?>" aria-label="Ticket QR code"></div></div><hr><div class="row g-4"><div class="col-sm-6"><div class="small muted">PARTICIPANT</div><strong><?=e($r['name'])?></strong></div><div class="col-sm-6"><div class="small muted">DATE & TIME</div><strong><?=e(date('M j, Y',strtotime($r['event_date'])))?></strong><div class="muted"><?=e(date('g:i A',strtotime($r['start_time'])))?><?= $r['end_time']?' – '.e(date('g:i A',strtotime($r['end_time']))):'' ?></div></div><div class="col-sm-6"><div class="small muted">VENUE</div><strong><?=e($r['venue'])?></strong></div><div class="col-sm-6"><div class="small muted">REGISTRATION ID</div><strong><?=e($r['registration_code'])?></strong></div><div class="col-sm-6"><div class="small muted">ENTRY CODE</div><strong class="fs-5 text-primary"><?=e($r['entry_code'])?></strong></div><div class="col-sm-6"><div class="small muted">STATUS</div><span class="status-pill <?=$checked?'status-checked':($r['status']==='valid'?'status-published':'status-cancelled')?>"><?=$checked?'Checked in':e(ucfirst($r['status']))?></span></div></div></div><div class="d-flex justify-content-center gap-2 mt-4"><button onclick="window.print()" class="btn btn-primary"><i class="bi bi-printer me-1"></i> Print / Save as PDF</button><a class="btn btn-outline-primary" href="my-events.php">Back to my events</a></div></div></section><style>@media print{nav,footer,.btn,.section-soft>a{display:none!important}body,.section-soft{background:white!important}.section{padding:0!important}.ticket{box-shadow:none;border:1px solid #bbb;max-width:100%}}</style><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script src="assets/js/ticket.js"></script><?php require __DIR__.'/includes/footer.php'; ?>
